package com.nigson.integration.notification;

import java.sql.Timestamp;
import java.security.interfaces.ECPublicKey;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import io.micrometer.core.instrument.MeterRegistry;
import com.nigson.integration.platform.*;
import com.nigson.integration.providers.TwilioAdapter;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import com.nigson.shared.security.ProviderHttp;

/** API-193 durable intent; owner-to-owner HTTP completes before its database transaction. */
public final class LeadReplyCommandService {
    private final JdbcTemplate jdbc;private final AuditWriter audit;private final MeterRegistry metrics;private final TransactionTemplate tx;
    private final StaffReplySource source;private final StaffReplyCrypto crypto;private final TwilioAdapter provider;private final Clock clock;private final UUID generation;private final String locale;private final int templateRevision;private final Map<String,ECPublicKey> actorKeys;private final Set<String> identityIssuers;private final Set<String> templates;private final String providerTemplateId;

    public LeadReplyCommandService(JdbcTemplate jdbc,AuditWriter audit,MeterRegistry metrics,PlatformTransactionManager manager,StaffReplySource source,StaffReplyCrypto crypto,TwilioAdapter provider,Clock clock,UUID generation,String locale,int templateRevision,Map<String,ECPublicKey> actorKeys,Set<String> identityIssuers,Set<String> templates,String providerTemplateId){
        this.jdbc=Objects.requireNonNull(jdbc);this.audit=Objects.requireNonNull(audit);this.metrics=Objects.requireNonNull(metrics);this.tx=new TransactionTemplate(Objects.requireNonNull(manager));this.tx.setTimeout(5);this.source=Objects.requireNonNull(source);this.crypto=Objects.requireNonNull(crypto);this.provider=Objects.requireNonNull(provider);this.clock=Objects.requireNonNull(clock);this.generation=Objects.requireNonNull(generation);this.locale=locale(locale);this.templateRevision=templateRevision;this.actorKeys=Map.copyOf(actorKeys);this.identityIssuers=Set.copyOf(identityIssuers);this.templates=Set.copyOf(templates);this.providerTemplateId=providerTemplateId;
        if(generation.equals(new UUID(0,0))||templateRevision<1||templateRevision>1000000||this.actorKeys.isEmpty()||this.actorKeys.size()>4||this.identityIssuers.isEmpty()||this.identityIssuers.size()>4||this.templates.size()>10||this.templates.stream().anyMatch(t->!t.equals("STAFF_LEAD_REPLY"))||providerTemplateId==null||!providerTemplateId.matches("HX[a-fA-F0-9]{32}"))throw new IllegalArgumentException("STAFF_REPLY_POLICY_INVALID");
    }

    public LeadReplyValues.Response enqueue(PrivateWorkload.Proof proof,String contextActorToken,LeadReplyValues.Command command,UUID correlation){
        authorize(proof);if(command==null||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();ActorAssertion.Actor contextActor=verifyContextActor(contextActorToken,command.leadId(),correlation);sameActor(proof.actor(),contextActor);
        byte[] canonical=LeadReplyValues.canonical(command);String hash=crypto.commandHash(canonical);UUID job=command.commandId();
        var replay=existing(command,hash);if(replay!=null)return replay;
        StaffReplySource.Context context=source.read(command.leadId(),correlation,contextActorToken);
        if(!context.eligible()||!context.channel().equals(command.channel())||!context.templates().contains(command.templateCode())||!templates.contains(command.templateCode()))throw rule();
        byte[] recipient=crypto.encrypt(job,"RECIPIENT",context.phone().getBytes(java.nio.charset.StandardCharsets.UTF_8));
        byte[] variables=crypto.encrypt(job,"VARIABLES",EventCodec.JSON.writeValueAsBytes(new TreeMap<>(command.variables())));
        return tx.execute(status->{local();jdbc.execute("SET LOCAL lock_timeout='750ms'");jdbc.execute("SET LOCAL statement_timeout='3s'");jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"staff-reply-command:"+job);
            var prior=jdbc.queryForList("SELECT j.id,j.business_key,j.owner_service,j.resource_id,j.template_code,j.channel,d.command_hash FROM integration.notification_job j LEFT JOIN integration.notification_dispatch d ON d.id=j.id WHERE j.id=? FOR UPDATE OF j",job);
            if(!prior.isEmpty()){verifyReplay(prior.getFirst(),command,hash);return new LeadReplyValues.Response(job,"PENDING");}
            var templateRows=jdbc.queryForList("SELECT id,revision,locale,body,provider_template_id,variables_schema::text FROM integration.notification_template WHERE code=? AND revision=? AND channel='WHATSAPP' AND classification='TRANSACTIONAL' AND active AND locale=? AND provider_template_id=? FOR SHARE",command.templateCode(),templateRevision,locale,providerTemplateId);
            if(templateRows.size()!=1)throw rule();var template=templateRows.getFirst();int revision=((Number)template.get("revision")).intValue();if(revision<1)throw rule();String contentSid=(String)template.get("provider_template_id");var schema=EventCodec.JSON.readTree(template.get("variables_schema").toString());validateTemplate(contentSid,(String)template.get("body"),schema,command.variables());
            ProviderHttp.Mode mode=provider.mode();String dbMode=mode==ProviderHttp.Mode.TEST?"SANDBOX":mode.name();String accountHash=provider.accountFingerprint();if(!accountHash.matches("[a-f0-9]{64}"))throw rule();
            jdbc.update("INSERT INTO integration.notification_job(id,created_by,updated_by,business_key,source_event_id,owner_service,resource_id,template_code,template_revision,classification,state,next_attempt_at,channel,destination_hash,provider_mode) VALUES (?,'api-193','api-193',?,?,'experience',?,'STAFF_LEAD_REPLY',?,'TRANSACTIONAL','PENDING',?,'WHATSAPP',?,?)",job,"staff-lead-reply:"+job,job,command.leadId(),revision,Timestamp.from(clock.instant()),context.destinationHash(),dbMode);
            var snapshot=EventCodec.JSON.createObjectNode();snapshot.put("id",template.get("id").toString());snapshot.put("code","STAFF_LEAD_REPLY");snapshot.put("revision",revision);snapshot.put("locale",locale);snapshot.put("channel","WHATSAPP");snapshot.put("classification","TRANSACTIONAL");snapshot.put("body",(String)template.get("body"));snapshot.put("providerTemplateId",contentSid);snapshot.set("variablesSchema",schema);
            jdbc.update("INSERT INTO integration.notification_dispatch(id,created_by,updated_by,template_id,locale,template_snapshot,template_hash,account_sid,messaging_service_sid,account_hash,generation,source_occurred_at,correlation_id,command_hash,recipient_ciphertext,variables_ciphertext,context_key_revision,context_basis) VALUES (?,'api-193','api-193',?,?,?::jsonb,?,?,?,?,?,?,?,?,?,?,?,?)",job,template.get("id"),locale,EventCodec.JSON.writeValueAsString(snapshot),EventCodec.hash(snapshot),provider.accountSid(),provider.messagingServiceSid(),accountHash,generation,Timestamp.from(clock.instant()),correlation,hash,recipient,variables,crypto.revision(),context.basis());
            String actor=proof.actor().party().toString();audit.append(actor,AuditValues.ActorKind.USER,AuditValues.Action.NOTIFICATION_DELIVERY,AuditValues.Resource.NOTIFICATION,job,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state","PENDING","channel","WHATSAPP","templateCode","STAFF_LEAD_REPLY"),null);
            metrics.counter("nigson.messaging.staff_reply.enqueued","channel","WHATSAPP","basis",context.basis()).increment();return new LeadReplyValues.Response(job,"PENDING");
        });
    }

    private LeadReplyValues.Response existing(LeadReplyValues.Command command,String hash){return tx.execute(status->{local();jdbc.execute("SET LOCAL statement_timeout='2s'");var rows=jdbc.queryForList("SELECT j.id,j.business_key,j.owner_service,j.resource_id,j.template_code,j.channel,d.command_hash FROM integration.notification_job j LEFT JOIN integration.notification_dispatch d ON d.id=j.id WHERE j.id=?",command.commandId());if(rows.isEmpty())return null;verifyReplay(rows.getFirst(),command,hash);return new LeadReplyValues.Response(command.commandId(),"PENDING");});}
    private void verifyReplay(Map<String,Object> row,LeadReplyValues.Command command,String hash){if(row.get("command_hash")==null)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);if(!command.commandId().equals(row.get("id"))||!("staff-lead-reply:"+command.commandId()).equals(row.get("business_key"))||!"experience".equals(row.get("owner_service"))||!command.leadId().equals(row.get("resource_id"))||!command.templateCode().equals(row.get("template_code"))||!command.channel().equals(row.get("channel"))||!hash.equals(row.get("command_hash")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);}
    private ActorAssertion.Actor verifyContextActor(String token,UUID lead,UUID correlation){String path="/internal/v1/leads/"+lead+"/messaging-context";var binding=new ActorAssertion.Binding("experience","notification.read_WITH_SIGNED_ACTOR","GET",path,correlation,ActorAssertion.Binding.bodyHash(new byte[0]));var actor=ActorAssertion.verify(token,binding,actorKeys,identityIssuers,clock);if(!actor.roles().contains("SALES")||!actor.scopes().contains("notification.read_WITH_SIGNED_ACTOR")||actor.organization()!=null)throw ActorAssertion.denied();return actor;}
    private static void sameActor(ActorAssertion.Actor a,ActorAssertion.Actor b){if(a==null||b==null||!a.party().equals(b.party())||!a.identityIssuer().equals(b.identityIssuer())||!a.identitySubject().equals(b.identitySubject())||!Objects.equals(a.organization(),b.organization())||!a.roles().equals(b.roles())||!Objects.equals(a.mfaAt(),b.mfaAt()))throw ActorAssertion.denied();}
    private static void authorize(PrivateWorkload.Proof p){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-193")&&r.owner().equals("integration")&&r.client().equals("nigson-commerce")).findFirst().orElseThrow(ActorAssertion::denied);if(p==null||!route.equals(p.route())||!route.client().equals(p.client())||p.actor()==null||!p.actor().roles().contains("SALES")||!p.actor().scopes().contains(route.scope())||p.actor().organization()!=null)throw ActorAssertion.denied();}
    private static void validateTemplate(String contentSid,String body,tools.jackson.databind.JsonNode schema,Map<String,String> variables){if(contentSid==null||!contentSid.matches("HX[a-fA-F0-9]{32}")||body==null||body.isBlank()||body.length()>1600||schema==null||!schema.isObject()||!schema.path("type").asString().equals("object")||!schema.path("additionalProperties").isBoolean()||schema.path("additionalProperties").asBoolean()||!schema.path("properties").isObject()||!schema.path("required").isArray())throw rule();var properties=schema.path("properties");var required=new HashSet<String>();for(var value:schema.path("required"))if(!value.isString()||!required.add(value.asString()))throw rule();if(!properties.propertyNames().containsAll(required)||!properties.propertyNames().containsAll(variables.keySet())||!variables.keySet().containsAll(required))throw rule();for(var field:properties.properties()){var definition=field.getValue();if(!definition.isObject()||!"string".equals(definition.path("type").asString())||!definition.path("maxLength").isIntegralNumber()||!definition.path("maxLength").canConvertToInt()||definition.path("maxLength").asInt()<1||definition.path("maxLength").asInt()>1000)throw rule();String value=variables.get(field.getKey());if(value!=null&&value.length()>definition.path("maxLength").asInt())throw rule();}}
    private static String locale(String raw){try{if(raw==null||raw.length()>16)throw new IllegalArgumentException();var l=new Locale.Builder().setLanguageTag(raw).build();if(l.getLanguage().isBlank())throw new IllegalArgumentException();return l.toLanguageTag();}catch(RuntimeException invalid){throw new IllegalArgumentException("STAFF_REPLY_LOCALE_INVALID");}}
    private static void local(){if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
    private static Problem.Failure rule(){return new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);}
}
